<?php $e = fn ($v) => App\Core\View::e((string) $v); ?>
<div class="section-heading"><div><p class="eyebrow">Movimentacoes</p><h1>Vai e Vem</h1><p>Registre e publique movimentacoes sem alterar automaticamente o vinculo oficial.</p></div><a class="button" href="<?= $e(App\Core\Config::url('/admin/vai-e-vem/novo')) ?>">Nova movimentacao</a></div>
<?php if (!empty($message)): ?><p class="flash-success"><?= $e($message) ?></p><?php endif; ?>
<form class="filter-bar" method="get" action="<?= $e(App\Core\Config::url('/admin/vai-e-vem')) ?>"><label>Busca <input name="q" value="<?= $e($filters['q']) ?>"></label><label>Tipo <select name="type"><option value="">Todos</option><?php foreach ($types as $type): ?><option value="<?= $e($type) ?>" <?= $filters['type'] === $type ? 'selected' : '' ?>><?= $e($type) ?></option><?php endforeach; ?></select></label><label>Status <select name="status"><option value="">Todos</option><?php foreach ($statuses as $status): ?><option value="<?= $e($status) ?>" <?= $filters['status'] === $status ? 'selected' : '' ?>><?= $e($status) ?></option><?php endforeach; ?></select></label><button type="submit">Filtrar</button></form>
<div class="table-wrap"><table><thead><tr><th>Atleta</th><th>Equipes</th><th>Tipo</th><th>Data</th><th>Status</th><th>Campeonato</th></tr></thead><tbody><?php foreach ($items as $item): ?><tr><td><a href="<?= $e(App\Core\Config::url('/admin/vai-e-vem/' . $item['id'])) ?>"><?= $e($item['sporting_name'] ?: $item['athlete_name']) ?></a></td><td><?= $e($item['previous_team_name'] ?: '-') ?> → <?= $e($item['new_team_name'] ?: '-') ?></td><td><?= $e($item['type']) ?></td><td><?= $e($item['movement_date']) ?></td><td><?= $e($item['status']) ?></td><td><?= $e($item['championship_name']) ?></td></tr><?php endforeach; ?><?php if (!$items): ?><tr><td colspan="6">Nenhuma movimentacao encontrada.</td></tr><?php endif; ?></tbody></table></div>
<?php if ($pages > 1): ?><nav class="pagination" aria-label="Paginacao"><?php for ($i = 1; $i <= $pages; $i++): ?><a class="<?= $i === $page ? 'active' : '' ?>" href="<?= $e(App\Core\Config::url('/admin/vai-e-vem?page=' . $i . '&q=' . urlencode($filters['q']) . '&type=' . urlencode($filters['type']) . '&status=' . urlencode($filters['status']))) ?>"><?= $i ?></a><?php endfor; ?></nav><?php endif; ?>
